function countdown(seconds, onTick, onDone) {
  let remaining = seconds;
  const id = setInterval(() => {
    remaining -= 1;
    onTick(remaining);
    if (remaining === 0) {
      clearInterval(id);
      onDone();
    }
  }, 1000);
  return () => clearInterval(id); // cancel function
}

